CREATE COLUMN TABLE "TEST_AP"."OTER" ("territryID" INTEGER CS_INT NOT NULL , "descript" NVARCHAR(200), "parent" INTEGER CS_INT DEFAULT -1 NOT NULL , "lindex" INTEGER CS_INT NOT NULL , "inactive" NVARCHAR(1) DEFAULT 'N', PRIMARY KEY ("territryID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTER_LOCATION" ON "TEST_AP"."OTER" ( "parent" ASC, "lindex" ASC );
CREATE INDEX "OTER_DESCRIPT" ON "TEST_AP"."OTER" ( "descript" ASC )